import{b as s,O as t,g as i,j as e}from"./chunks/framework.DSt9LnBW.js";const k=JSON.parse('{"title":"Lantern Harness AI 工作台上线了","description":"Lantern Harness 是一个跑在本地的 AI 工作台。它可以把对话、需求、用例、提示词、知识库、待办与测试统计放在同一个数据空间里，用插件组合出你需要的那部分；模型走 BYOK（自带密钥）直连，数据存放在本地数据空间中。它不是\\"又一个 AI 聊天框\\"。它想解决的是聊天框之外的那些事。","frontmatter":{"date":"2026-10-19T00:00:00.000Z","pin":true,"tags":["产品","本地优先","AI 工作台"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/internet-years/lantern-harness-launch/index.md","filePath":"个人博客/在互联网的那些年/4.Lantern Harness AI 工作台上线了.md","lastUpdated":1792341560000}'),n={name:"blog/internet-years/lantern-harness-launch/index.md"};function l(p,a,h,o,r,d){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="lantern-harness-ai-工作台上线了" tabindex="-1">Lantern Harness AI 工作台上线了 <a class="header-anchor" href="#lantern-harness-ai-工作台上线了" aria-label="Permalink to &quot;Lantern Harness AI 工作台上线了&quot;">​</a></h1><h2 id="lantern-harness是什么" tabindex="-1">Lantern Harness是什么？ <a class="header-anchor" href="#lantern-harness是什么" aria-label="Permalink to &quot;Lantern Harness是什么？&quot;">​</a></h2><p>Lantern Harness 是一个跑在本地的 AI 工作台。它可以把对话、需求、用例、提示词、知识库、待办与测试统计放在同一个数据空间里，用插件组合出你需要的那部分；模型走 BYOK（自带密钥）直连，数据存放在本地数据空间中。</p><p>它不是&quot;又一个 AI 聊天框&quot;。它想解决的是聊天框之外的那些事。</p><p>线上版本访问：<a href="https://lantern.yychuiyan.com/" target="_blank" rel="noreferrer">在线地址</a></p><p>如果真实体验的话推荐安装本地服务。</p><h2 id="一、为什么要做它" tabindex="-1">一、为什么要做它 <a class="header-anchor" href="#一、为什么要做它" aria-label="Permalink to &quot;一、为什么要做它&quot;">​</a></h2><p>过去一年，很多人把 AI 用进了日常工作，我也在想怎么能够更好地把 AI 运用到工作中，所以自己做了一个 AI 工作台，现在还在迭代中。做这个平台，主要是想解决几个痛点。</p><p><strong>第一，工作资料散在各处。</strong></p><p>需求在一个文档里，用例在 Excel 里，待办在另一个 App 里，日报靠回忆拼。AI 只能看到你手动粘贴的那一小块，看不到全貌，也就没法真正帮你把事情往下推。</p><p><strong>第二，数据不敢往外放。</strong></p><p>测试岗位接触的东西往往很敏感：未发布的需求、线上缺陷、内部接口文档、客户名单。把这些贴进一个云端对话框，很多人心里是不踏实的。可如果不贴，AI 就只能给出泛泛而谈的答案。</p><p><strong>第三，生成的东西留不下来。</strong></p><p>对话里生成的用例、提示词、周报，用完就散在聊天记录里；下次想改，说不清改的是哪一版，评审、归档、统计也接不上。没有落成文件，就很难进入真实的工作流。</p><p><strong>一个放在本机、资料各有归处、产出能直接落成文件、还能被插件扩展的工作台。</strong></p><p>&quot;提灯的人不问路&quot;是放在首页的那句话。灯是你自己的，路也是你自己走的；工具只负责把脚下照亮。</p><h2 id="二、设计上的三个取舍" tabindex="-1">二、设计上的三个取舍 <a class="header-anchor" href="#二、设计上的三个取舍" aria-label="Permalink to &quot;二、设计上的三个取舍&quot;">​</a></h2><h3 id="_1-数据是文件-不是数据库里的记录" tabindex="-1">1. 数据是文件，不是数据库里的记录 <a class="header-anchor" href="#_1-数据是文件-不是数据库里的记录" aria-label="Permalink to &quot;1. 数据是文件，不是数据库里的记录&quot;">​</a></h3><p>一个&quot;数据空间&quot;就是你磁盘上的一个普通文件夹。你可以用 Finder 打开它、用 Git 管它、打包发给同事，或者直接扔进网盘。</p><p>内容按目录存放，目录名就是侧栏里的名字：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需求文档库/        需求文档（.md / .txt / .docx）</span></span>
<span class="line"><span>用例管理/          生成的测试用例</span></span>
<span class="line"><span>提示词管理/        提示词与每个空间的默认提示词</span></span>
<span class="line"><span>知识库管理/        规范、方法论、环境约定</span></span>
<span class="line"><span>测试模板库/        用例与报告模板</span></span>
<span class="line"><span>待办事项/待办.json</span></span>
<span class="line"><span>任务管理/任务.json</span></span>
<span class="line"><span>测试统计/测试统计.json</span></span>
<span class="line"><span>用例执行统计/用例执行统计.json</span></span>
<span class="line"><span>工作汇报/          日报 / 周报 / 月报</span></span></code></pre></div><p>这意味着：你写的东西不会被锁在一个 SaaS 里。哪天不想用了，文件还在；想换工具，文件还是标准的 Markdown / JSON。<code>.lantern/</code> 里放的是空间清单、会话与记忆这类元数据，已加入 <code>.gitignore</code>，不会误提交。</p><p>目录是<strong>按需创建</strong>的。新建一个空间，里面只有隐藏的 <code>.lantern/</code>；开了哪个内容库插件，才会铺出对应目录和种子文件。没有一堆用不上的空文件夹。</p><h3 id="_2-插件是开关-不是下载安装" tabindex="-1">2. 插件是开关，不是下载安装 <a class="header-anchor" href="#_2-插件是开关-不是下载安装" aria-label="Permalink to &quot;2. 插件是开关，不是下载安装&quot;">​</a></h3><p>平台的能力都收在&quot;我的插件&quot;里，按用途分成内容库、生成能力、记忆与检索、待办与效率、测试统计、仪表盘、开发工具七类。打开一个开关，侧栏就多一个入口；关掉，入口消失，磁盘上的数据原样保留。</p><p>这件事的好处是：<strong>每个人的工作台长得不一样。</strong></p><ul><li>只写用例的人，开&quot;用例管理 + 生成测试用例 + 测试模板库&quot;就够了。</li><li>带项目的人，再开&quot;任务管理 + 待办事项 + 仪表盘&quot;。</li><li>做团队知识沉淀的人，开&quot;知识库管理 + 知识库检索 + 会话记忆&quot;。</li></ul><p>插件之间不是孤立的。任务和待办共享同一份数据，仪表盘直接聚合它们；生成用例时会读需求文档和你选的模板；工作汇报会用到提示词管理里那份可编辑的提示词。这是&quot;一个空间里的一套东西&quot;，而不是七个互不相干的页面。</p><p><img src="https://op.yychuiyan.com/docs-blog/lantern-plugins.png" alt="我的插件页面：按内容库、生成能力、记忆与检索、待办与效率、测试统计、仪表盘、开发工具分组，每项一个开关"></p><h3 id="_3-模型是你的-密钥也是你的" tabindex="-1">3. 模型是你的，密钥也是你的 <a class="header-anchor" href="#_3-模型是你的-密钥也是你的" aria-label="Permalink to &quot;3. 模型是你的，密钥也是你的&quot;">​</a></h3><p>平台不代售 token。你在&quot;设置&quot;里填自己的密钥，选提供商、模型和推理等级，请求从本机直连模型服务商。换模型不需要迁移数据，换数据空间也不需要重新配模型。</p><h2 id="三、主要能力" tabindex="-1">三、主要能力 <a class="header-anchor" href="#三、主要能力" aria-label="Permalink to &quot;三、主要能力&quot;">​</a></h2><h3 id="工作台-一个能动手的对话界面" tabindex="-1">工作台：一个能动手的对话界面 <a class="header-anchor" href="#工作台-一个能动手的对话界面" aria-label="Permalink to &quot;工作台：一个能动手的对话界面&quot;">​</a></h3><p>对话本身该有的都有：流式输出、思考与工具步骤折叠、上下文过长自动摘要、手动压缩、生成中可停止。</p><p>在此之上，有几处是我们花了很多时间的：</p><ul><li><strong>回合可重连</strong>。有本地服务时，生成过程在服务端跑；刷新页面或切到别的页面再回来，回合还在，不会白等一场。</li><li><strong>回合 Tab</strong>。按轮次回看每一轮的输入输出；想从某一轮重来，点&quot;从此处继续&quot;，它会截断到那一轮并自动发出&quot;请从第 N 轮继续&quot;。</li><li><strong>看得见的成本</strong>。每条回复都标了用量、模型用时、工具用时、首字延迟（TTFT）和生成速度（TPS）。哪个模型快、哪次调用贵，不用猜。</li><li><strong>计划模式</strong>。进入后模型在探查阶段只读不改，先交方案（<code>submit_plan</code>），你批准了才动手。改代码之前先对齐思路，比事后回滚便宜。</li><li><strong>目标与定时</strong>。可以给一个会话设定长期目标，写进系统提示，模型会按目标持续推进；也可以让模型建定时任务，到点用系统通知把消息送回原会话。</li><li><strong>子代理与工作流</strong>。复杂任务可以派生子代理并行处理，主线程不必被一串工具调用堵住。</li></ul><p>输入区支持 <code>+</code> 添加文件与附件、<code>@</code> 引用知识库与模板文档、<code>/</code> 唤起已启用的生成类插件。附件支持文本、Excel、Word（Word 会转成正文），图片可以直接粘贴。</p><p><img src="https://op.yychuiyan.com/docs-blog/lantern-workbench.png" alt="Lantern Harness 工作台新会话页面：左侧是分组的侧栏菜单，中间是输入框与扩展插件入口，右侧是会话列表"></p><h3 id="本地工具与权限-让-ai-真的能干活" tabindex="-1">本地工具与权限：让 AI 真的能干活 <a class="header-anchor" href="#本地工具与权限-让-ai-真的能干活" aria-label="Permalink to &quot;本地工具与权限：让 AI 真的能干活&quot;">​</a></h3><p>只有聊天能力的 AI，最后还是要你自己复制粘贴。所以我们把本地能力做进了会话：文件读写、<code>glob</code> / <code>grep</code> 搜索、<code>bash</code> 与 PowerShell（含持久会话和后台任务）、网页搜索与抓取、Office 转 PDF、按需加载工作区 Skill。</p><p>同时给了一把刹车——访问权限三档：</p><table tabindex="0"><thead><tr><th>档位</th><th>行为</th></tr></thead><tbody><tr><td>仅可查看</td><td>只读与搜索，不提供写入，命令执行不可用</td></tr><tr><td>工作区内修改</td><td>可在工作区读写，命令的工作目录限定在工作区内</td></tr><tr><td>完全权限</td><td>放开工作区外路径与更大范围的命令执行</td></tr></tbody></table><p>工作区默认就是当前空间目录。模型还会自动读取工作区里的 <code>AGENTS.md</code> / <code>CLAUDE.md</code>，把项目约定带进每次对话——这比在提示词里反复强调&quot;我们项目用 pnpm&quot;要可靠得多。</p><h3 id="会话记忆-跨对话记住你" tabindex="-1">会话记忆：跨对话记住你 <a class="header-anchor" href="#会话记忆-跨对话记住你" aria-label="Permalink to &quot;会话记忆：跨对话记住你&quot;">​</a></h3><p>记忆不是&quot;把所有聊天记录塞进上下文&quot;，那样既贵又乱。我们把它拆成五条轨：</p><ul><li><strong>用户档案</strong>：你的偏好与习惯，跨项目生效。</li><li><strong>全局事实</strong>：长期有效的事实性信息。</li><li><strong>项目关键</strong>：某个项目的约定、架构、坑。</li><li><strong>项目日志</strong>：进展流水，可写但不注入。</li><li><strong>每日日志</strong>：按天归档。</li></ul><p>前三条会注入对话。重要的新事实不会直接落库，而是先进入&quot;待确认记忆建议&quot;，你点了采纳才写入并开始生效。记忆是 <code>.lantern/local/memories/</code> 下的 Markdown，可以自己打开看、自己改——我们不想让&quot;AI 记住了什么&quot;变成一个黑盒。</p><h3 id="内容库与生成能力-把团队资产用起来" tabindex="-1">内容库与生成能力：把团队资产用起来 <a class="header-anchor" href="#内容库与生成能力-把团队资产用起来" aria-label="Permalink to &quot;内容库与生成能力：把团队资产用起来&quot;">​</a></h3><p>内容库现在有五个：需求文档、测试用例、提示词、知识库、测试模板，各自对应一类资产。但它不是一个写死的清单：缺哪一类资料，按「插件开发」长一个新库就行——和内置的库一样出现在侧栏，用同一套文件规范，AI 也认得。</p><p>生成类插件（生成测试用例 / 生成提示词 / 生成知识库）走的是同一条路：用 <code>/</code> 打开配置，选类型、模板和提示词，对话生成，<strong>质检通过后</strong>写入对应目录。写入的是普通文件，之后照常编辑、评审、进 Git。</p><p>&quot;知识库检索&quot;则解决输入侧的问题：在输入框敲 <code>@</code>，直接从知识库、模板库或工作区文档里挑，文档随消息一起发出去。模型不用猜你的规范在哪，你也不用每次手动贴一遍。</p><p><img src="https://op.yychuiyan.com/docs-blog/lantern-prompts.png" alt="提示词管理页面：列出当前空间里的提示词文件、修改时间与大小，可在会话中打开或删除"></p><h3 id="待办、任务、汇报与统计-让-ai-和你看同一份数据" tabindex="-1">待办、任务、汇报与统计：让 AI 和你看同一份数据 <a class="header-anchor" href="#待办、任务、汇报与统计-让-ai-和你看同一份数据" aria-label="Permalink to &quot;待办、任务、汇报与统计：让 AI 和你看同一份数据&quot;">​</a></h3><p>这部分是最容易被低估的价值。几个页面各自对应一类事情，但底下是同一套数据。</p><h4 id="待办事项" tabindex="-1">待办事项 <a class="header-anchor" href="#待办事项" aria-label="Permalink to &quot;待办事项&quot;">​</a></h4><p>按状态、紧急程度筛选，行内改状态，支持开始 ~ 截止区间。工作台里的 AI 可以通过工具直接增删改同一份待办。</p><p><img src="https://op.yychuiyan.com/docs-blog/lantern-todos.png" alt="待办事项页面：按状态分组，每行可改状态、紧急程度与起止日期，顶部显示待开始、进行中与已完成的数量"></p><h4 id="任务管理" tabindex="-1">任务管理 <a class="header-anchor" href="#任务管理" aria-label="Permalink to &quot;任务管理&quot;">​</a></h4><p>任务池 / 进行中 / 已完成 / 已关闭 / 已取消，按任务汇总关联待办的数量和完成进度。</p><p><img src="https://op.yychuiyan.com/docs-blog/lantern-tasks.png" alt="任务管理页面：顶部按任务池、进行中、已完成、已关闭、已取消分栏，表格里汇总每个任务下关联待办的数量与完成进度"></p><h4 id="工作汇报" tabindex="-1">工作汇报 <a class="header-anchor" href="#工作汇报" aria-label="Permalink to &quot;工作汇报&quot;">​</a></h4><p>日报 / 周报 / 月报三个 Tab，提示词可以自己改，也可以从提示词库里另选一份；生成的汇报按类型存进 <code>工作汇报/</code>。</p><h4 id="测试统计" tabindex="-1">测试统计 <a class="header-anchor" href="#测试统计" aria-label="Permalink to &quot;测试统计&quot;">​</a></h4><p>按日期和维度（功能用例、自动化用例、接口用例、测试报告、缺陷统计等）记录数量，维度可搜索可新建。</p><p><img src="https://op.yychuiyan.com/docs-blog/lantern-test-stats.png" alt="测试统计页面：按日期与测试维度记录数量，维度可以是功能用例、自动化用例、接口用例、测试报告、缺陷统计"></p><h4 id="用例执行统计" tabindex="-1">用例执行统计 <a class="header-anchor" href="#用例执行统计" aria-label="Permalink to &quot;用例执行统计&quot;">​</a></h4><p>按项目记录用例总数、待执行、已执行，自动算剩余与执行比例。</p><p><img src="https://op.yychuiyan.com/docs-blog/lantern-case-exec.png" alt="用例执行统计页面：按项目记录用例总数、待执行与已执行，自动算出当前剩余与执行比例"></p><p>关键在于，这些不是给 AI &quot;看&quot;的报表，而是 AI 能读也能写的<strong>同一份数据</strong>。你说&quot;把今天的用例执行情况记一下&quot;，它写进去的就是你在页面上看到的那条记录，不存在两边对不上。</p><h3 id="仪表盘-一页看完今天" tabindex="-1">仪表盘：一页看完今天 <a class="header-anchor" href="#仪表盘-一页看完今天" aria-label="Permalink to &quot;仪表盘：一页看完今天&quot;">​</a></h3><p>仪表盘把当前空间的待办、任务和测试统计聚合成六张卡片：待办概览、休息倒计时、今日待办、进行中任务、测试统计柱状图、待办日历。</p><p>排布用的是 12 列坐标画布：每张卡记自己的列 / 行 / 宽 / 高，想放哪放哪，同一行的卡片不再互相等高；右下角可以独立拖宽拖高，挡住邻居就把它顺势往下推，双击恢复默认大小。窄屏（手机、分栏）会自动堆成一列，不会把日历挤成一条。</p><p>休息倒计时按法定节假日和调休补班算。2026 年的正式安排和 2027 年的法定假日已经录进 <code>public/cn-holidays.json</code>；每年国务院办公厅发通知后，往 JSON 里加一年就行，逻辑不用动。</p><p>这里的组件现在还比较少，好的地方是自己可以定制开发想要的组件。</p><p><img src="https://op.yychuiyan.com/docs-blog/lantern-dashboard.png" alt="仪表盘页面：待办概览、休息倒计时、今日待办、进行中任务与测试统计几张卡片拼在一起，可拖动排序、拖角改宽高"></p><h3 id="插件开发-让平台长成你需要的样子" tabindex="-1">插件开发：让平台长成你需要的样子 <a class="header-anchor" href="#插件开发-让平台长成你需要的样子" aria-label="Permalink to &quot;插件开发：让平台长成你需要的样子&quot;">​</a></h3><p>平台内置的是通用能力。真到自己干活，总会缺一块：可能是一个新的资料库，可能是一个只在你的团队存在的流程。这部分不用等版本更新——「插件开发」就是留给你自己长的口子。</p><h4 id="插件可以长成四种样子" tabindex="-1">插件可以长成四种样子 <a class="header-anchor" href="#插件可以长成四种样子" aria-label="Permalink to &quot;插件可以长成四种样子&quot;">​</a></h4><p>先想清楚要做的是哪一类，再动手：</p><table tabindex="0"><thead><tr><th>形态</th><th>长什么样</th><th>适合什么</th></tr></thead><tbody><tr><td>纯提示词型</td><td>一个「+」里的胶囊，激活后按固定提示词工作</td><td>一类固定的分析、改写、评审任务</td></tr><tr><td>带配置面板</td><td>打开抽屉先选类型 / 模板 / 提示词，确认后进会话</td><td>生成类：用例、提示词、知识库</td></tr><tr><td>侧栏库</td><td>侧栏多一个入口，点进去是自己的页面</td><td>需要浏览、筛选、增删改的资料</td></tr><tr><td>本地服务</td><td>前端页面 + 一个 <code>lh-plugins/</code> 下的中间件</td><td>要读写磁盘、要自己的接口</td></tr></tbody></table><p>我们内部很多能力就是这么长出来的：先有一个具体需求，再决定它该是胶囊、抽屉，还是单独一个菜单页。</p><h4 id="菜单页面-侧栏多一个入口" tabindex="-1">菜单页面：侧栏多一个入口 <a class="header-anchor" href="#菜单页面-侧栏多一个入口" aria-label="Permalink to &quot;菜单页面：侧栏多一个入口&quot;">​</a></h4><p>「侧栏库」这一类，落到界面上就是<strong>菜单页面</strong>：左侧多一个入口，点开是一个完整页面，而不是会话里的一个弹层。</p><p>它和内置的待办、任务、仪表盘是同一种东西：</p><ul><li>入口按插件开关显示。关掉插件，入口消失，<strong>磁盘上的数据原样保留</strong>，再打开还在。</li><li>入口可以拖顺序、归到分组里（支持一层子分组）、换图标，和内置菜单一起排。</li><li>页面自己管自己的数据目录，通常是当前空间下的一个文件夹；也能直接读写内置插件的那份数据。</li><li>页面里的操作和会话里的 AI 用的是同一份数据——页面上改一条，AI 读到的就是改后的；反过来也一样。</li></ul><p>这也是它和「接一个第三方工具」的区别：不是嵌一个 iframe 进来，而是这个页面本身就在工作台里，知道当前空间是谁、数据放在哪、AI 能碰哪些文件。</p><h4 id="用-ai-开发-先说清楚-再让它动手" tabindex="-1">用 AI 开发：先说清楚，再让它动手 <a class="header-anchor" href="#用-ai-开发-先说清楚-再让它动手" aria-label="Permalink to &quot;用 AI 开发：先说清楚，再让它动手&quot;">​</a></h4><p>流程是固定的，不需要你写代码：</p><ol><li><code>+</code> →「扩展插件」→「插件开发」，输入框上方出现胶囊。</li><li>直接用中文描述需求：做什么、给谁用、希望从哪里进入。</li><li>模型先<strong>只读</strong>看代码，然后给你 2～4 个选择题：插件形态、范围边界、命名与入口、新空间里默认开还是关。</li><li><strong>你确认之后才改文件</strong>。跳过、关掉提问卡片、不回复，都不算确认。</li><li>完成后插件并进「扩展插件」，在「我的插件」里打开就能用。</li></ol><p><img src="https://op.yychuiyan.com/docs-blog/lantern-plus-menu.png" alt="工作台输入框的加号菜单：文件、目标、计划、待办、任务、扩展插件、指令，其中扩展插件下就是插件开发"></p><p>确认这一步是有意做重的。让 AI 直接改源码很快，但改错方向再回滚更慢；先把「做成哪种形态、从哪进、默认开不开」对齐，返工少很多。</p><h4 id="一个例子-把「灵光任务」这类东西长进来" tabindex="-1">一个例子：把「灵光任务」这类东西长进来 <a class="header-anchor" href="#一个例子-把「灵光任务」这类东西长进来" aria-label="Permalink to &quot;一个例子：把「灵光任务」这类东西长进来&quot;">​</a></h4><p>我自己之前单独做过一个任务应用，叫<strong>灵光任务</strong>：待办和任务分两层，任务下挂待办、自动算完成进度；再往上还有项目、迭代、需求、缺陷四层，需求能关联 GitHub Issue；另外有日历排期和笔记。</p><p>它是一个独立的 Web 应用——前端、后端、数据库、登录都要自己维护一套。而这类需求里，真正跟别人不一样的往往只有中间那一小块：你们的任务怎么分层、缺陷怎么流转、日报按什么口径统计。为了这一小块，去养一整套应用，代价不小。</p><p>放到工作台里，这类功能可以拆成插件长进来：</p><ul><li>「任务 + 待办」已经有内置插件，共用同一份 <code>任务管理/</code>、<code>待办事项/</code> 数据；</li><li>缺的「项目 / 迭代 / 需求 / 缺陷」是一组新的菜单页面，数据落在空间里自己的目录；</li><li>需求关联 Issue、按迭代看进度，是页面里的逻辑，不涉及新的账号体系；</li><li>仪表盘、工作汇报直接读这些数据，不用再做一次对接。</li></ul><p>要加的时候，描述清楚三件事就够了：<strong>它和现有待办是什么关系、从哪个入口进、数据放在哪个目录</strong>。剩下的形态选择，模型会在确认环节问你。</p><h4 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h4><p>这条路不适合所有人：它改的是仓库源码，需要本地服务和源码读写权限，开发服热更新；生成的新插件会跟着仓库一起走，升级时要自己合并。如果你只是想要一个开箱即用的工具，内置插件目前也已经够用；如果你有一块反复出现的、平台没有的活，自己长一个往往比再接一个工具更省事。</p><h3 id="不只有界面-cli、json-rpc-与-acp" tabindex="-1">不只有界面：CLI、JSON-RPC 与 ACP <a class="header-anchor" href="#不只有界面-cli、json-rpc-与-acp" aria-label="Permalink to &quot;不只有界面：CLI、JSON-RPC 与 ACP&quot;">​</a></h3><p>界面之外，同一套能力可以从命令行和外部程序进入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;帮我总结今天的待办&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 无界面单轮问答</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rpc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # 以 stdio JSON-RPC 暴露本地问答能力</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # 以 ACP 子集供外部编排驱动</span></span></code></pre></div><p>日常运维也一样在命令行：<code>lantern status</code> / <code>doctor</code> / <code>logs</code> / <code>update</code>，数据空间用 <code>lantern space list | add | use</code> 管理。想接到自己的脚本或 CI 里，不必绕过界面爬页面，下面会详细介绍在本地如何使用。</p><h2 id="四、它适合谁-不适合谁" tabindex="-1">四、它适合谁，不适合谁 <a class="header-anchor" href="#四、它适合谁-不适合谁" aria-label="Permalink to &quot;四、它适合谁，不适合谁&quot;">​</a></h2><p><strong>适合：</strong></p><ul><li>测试 / QA 同学：需求、用例、执行统计、日报在一条线上，不用来回倒腾。</li><li>需要长期跟一个项目的独立开发者或小团队：希望 AI 记得项目约定，而不是每次从零解释。</li><li>对数据位置敏感的人：文档不能上传，但确实想用 AI 提效。</li><li>喜欢&quot;文件即数据&quot;的人：想用 Git 管知识库，想用编辑器改提示词。</li><li>有自己一套固定流程的人：内置的差一块，就自己长一个插件，不用再开一个新系统。</li></ul><p><strong>不适合：</strong></p><ul><li>想要开箱即用、完全不想碰命令行的多人协作团队。目前它是单机产品，没有云端协同。</li><li>期待平台自带模型额度的人。BYOK 意味着你得自己准备密钥。</li><li>想用它替代 IDE 的人。它能读写文件、能跑命令，但它是工作台，不是编辑器。</li></ul><h2 id="五、安装与使用" tabindex="-1">五、安装与使用 <a class="header-anchor" href="#五、安装与使用" aria-label="Permalink to &quot;五、安装与使用&quot;">​</a></h2><h3 id="_1-准备环境" tabindex="-1">1. 准备环境 <a class="header-anchor" href="#_1-准备环境" aria-label="Permalink to &quot;1. 准备环境&quot;">​</a></h3><p>需要 Node.js 22.22 及以上，macOS / Windows / Linux 都行，不用 Docker，也不用另装数据库。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 确认 &gt;= v22.22</span></span></code></pre></div><p>版本不够就装个新的 LTS，或者用 nvm / fnm 切一下。</p><h3 id="_2-装命令" tabindex="-1">2. 装命令 <a class="header-anchor" href="#_2-装命令" aria-label="Permalink to &quot;2. 装命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lantern-harness</span></span></code></pre></div><p>跑完会注册一个全局短命令 <code>lantern</code>（npm 包名是 <code>lantern-harness</code>，命令是 <code>lantern</code>）。装完先确认一下：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 检查 Node 版本、端口占用、配置是否正常</span></span></code></pre></div><p>以后升级用 <code>lantern update</code>，正在跑的服务会自动停掉、装完再拉起来；卸载用 <code>lantern uninstall</code>，只删命令，数据空间留着。</p><h3 id="_3-配置数据空间" tabindex="-1">3. 配置数据空间 <a class="header-anchor" href="#_3-配置数据空间" aria-label="Permalink to &quot;3. 配置数据空间&quot;">​</a></h3><p>数据空间就是磁盘上的一个普通文件夹，你的文档、用例、待办、会话都放在里面。第一次必须先指定：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>选择数据目录：</span></span>
<span class="line"><span>  1) 打开系统文件夹选择器</span></span>
<span class="line"><span>  2) 当前目录（当前终端所在位置）</span></span>
<span class="line"><span>  3) 自定义路径（手输）</span></span>
<span class="line"><span>请输入 1 / 2 / 3（默认 1）：</span></span></code></pre></div><p>三个选项分别是：系统弹窗里挑一个目录、把当前终端所在目录当成数据目录、直接手输路径。建议挑一个你平时会备份的位置，比如 <code>~/Documents/AI数据空间</code>。</p><p>选完用三条命令确认：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 当前数据空间的绝对路径</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 配置文件位置（macOS 在 ~/.config/lantern-harness/config.json）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> space</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 数据目录里有哪些空间，当前是哪个</span></span></code></pre></div><p>初始化会在这个目录里铺出「公共空间」，并把这项记进配置，之后 <code>lantern web</code> 都读这份配置。<strong>数据目录被移动、改名或删掉之后，重新 <code>lantern init</code> 指一次就行</strong>，里面的文件不会动。</p><p>一个数据目录下可以放多个空间，彼此完全隔离：用例、提示词、待办、会话、模型配置各一份，切换时互不串。命令行能管：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> space</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 会员中心</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --use</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 新建空间并设为当前</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> space</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 会员中心</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 切过去（重启服务后生效）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> space</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 会员中心</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 导出 zip，备份或给同事</span></span></code></pre></div><p>界面上也有对应的入口：左上角点当前空间名 →「管理空间」，可以新增、编辑（改名、改默认提示词）、复制、移出列表。把别人的空间文件夹整个拷进数据目录后，点「扫描文件夹」就能纳管，不用重装。</p><h3 id="_4-启动并打开" tabindex="-1">4. 启动并打开 <a class="header-anchor" href="#_4-启动并打开" aria-label="Permalink to &quot;4. 启动并打开&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span></span></code></pre></div><p>默认监听 <code>127.0.0.1:4321</code>，浏览器打开这个地址即可（或 <code>lantern open</code> 直接拉起）。常用几条：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 在不在跑、端口、当前数据空间</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 停止</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 重启</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lantern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 出问题时看日志</span></span></code></pre></div><p><code>lantern web</code> 默认后台启动；想在当前终端前台跑、直接看输出，加 <code>--foreground</code>。端口写在配置文件里（<code>lantern config</code> 能看到路径），默认 4321，被占用时改这一项就好。</p><h3 id="_5-配模型-byok" tabindex="-1">5. 配模型（BYOK） <a class="header-anchor" href="#_5-配模型-byok" aria-label="Permalink to &quot;5. 配模型（BYOK）&quot;">​</a></h3><p>点侧栏底部「设置」→「模型」→「+ 添加模型提供商」，填任意 OpenAI 兼容接口：</p><table tabindex="0"><thead><tr><th>预设</th><th>Base URL</th><th>模型示例</th></tr></thead><tbody><tr><td>DeepSeek</td><td><code>https://api.deepseek.com/v1</code></td><td><code>deepseek-flash</code></td></tr><tr><td>通义千问</td><td><code>https://dashscope.aliyuncs.com/compatible-mode/v1</code></td><td><code>qwen-plus</code></td></tr><tr><td>OpenAI</td><td><code>https://api.openai.com/v1</code></td><td><code>gpt-4o-mini</code></td></tr><tr><td>自定义</td><td>任意 OpenAI 兼容端点</td><td>任意模型名</td></tr></tbody></table><p>模型名不用手抄：填完 Key 再点模型下拉，它会实时请求端点的 <code>GET /models</code> 拉候选列表。可以加多个提供商，在输入框右侧随时切；旁边的推理等级选 Low / High / Max，分别是快、均衡、深推理。</p><p>Key 只写在本机（本地服务写进 <code>.lantern/local/app.config.json</code>），不进仓库，也不会上传。所以换电脑要重配一次，公共电脑上别填。</p><h3 id="_6-打开需要的插件" tabindex="-1">6. 打开需要的插件 <a class="header-anchor" href="#_6-打开需要的插件" aria-label="Permalink to &quot;6. 打开需要的插件&quot;">​</a></h3><p>新空间只有「我的工作台」「提示词管理」「帮助中心」三个入口。进「我的插件」，按分类把要用的打开：内容库、生成能力、记忆与检索、待办与效率、测试统计、仪表盘、开发工具。</p><p>打开的那一刻，对应目录才会在空间里铺出来——开了「测试统计」才开始有 <code>测试统计/测试统计.json</code>，不用的不会留一堆空文件夹。关掉只是隐藏入口，磁盘上的文件原样保留。仪表盘第一次打开是空白画布，点「编辑组件」自己挑卡片，这是故意的，我们不想替你做决定。</p><h3 id="_7-源码方式-可选" tabindex="-1">7. 源码方式（可选） <a class="header-anchor" href="#_7-源码方式-可选" aria-label="Permalink to &quot;7. 源码方式（可选）&quot;">​</a></h3><p>要改代码或做插件开发：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/yychuiyan/lantern-harness.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lantern-harness</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 开发模式，热更新，带本地落盘 API</span></span></code></pre></div><p>目录约定、每个插件的细节在<a href="https://lantern.yychuiyan.com/docs/manual/" target="_blank" rel="noreferrer">操作手册</a>，安装相关的原文在<a href="https://lantern.yychuiyan.com/docs/install/" target="_blank" rel="noreferrer">安装手册</a>。项目是 MIT 协议，仓库在 <a href="https://github.com/yychuiyan/lantern-harness" target="_blank" rel="noreferrer">yychuiyan/lantern-harness</a>。</p><h2 id="六、最后" tabindex="-1">六、最后 <a class="header-anchor" href="#六、最后" aria-label="Permalink to &quot;六、最后&quot;">​</a></h2><p>做这个平台的这段时间，我反复提醒自己一件事：<strong>AI 的价值不在对话本身，而在它能不能进入你真实的工作流。</strong></p><p>真实的工作流里有一堆不性感的东西——目录结构、模板、状态字段、分页、权限、数据放哪、刷新后还在不在。这些做不好，模型再强也只是个玩具。</p>`,149)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
